#include <stdio.h>
#include <stdlib.h>

int main() {
    int N;
    scanf("%d", &N);
    int *xs = malloc(N * sizeof(int));
    int *ys = malloc(N * sizeof(int));
    int maxY = 0;
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &xs[i], &ys[i]);
        if (ys[i] > maxY) maxY = ys[i];
    }

    // We'll keep a grid of toggles; coordinates can be large but we only
    // need up to maxY + 1 rows and a reasonable width.
    // Actually we can do it with a dictionary/hashmap but N <= ? (not given),
    // assume small for this solution style.
    // Use a simple approach: store counts in a 2D array with offset.
    int offset = 2000; // arbitrary large enough
    int width = 4000;
    int height = maxY + 2;
    int **grid = malloc(height * sizeof(int*));
    for (int i = 0; i < height; i++) {
        grid[i] = calloc(width, sizeof(int));
    }

    for (int i = 0; i < N; i++) {
        grid[ys[i]][xs[i] + offset] = 1;
    }

    // Process from top row downward
    for (int y = maxY; y >= 0; y--) {
        for (int x = -y; x <= y; x++) { // possible range for triangular grid
            int idx = x + offset;
            if (idx < 0 || idx >= width-1) continue;
            int val = grid[y][idx];
            if (val) {
                // apply reverse operation: toggle (x,y), (x,y+1), (x+1,y)
                // But we are going backwards: if lamp is on here,
                // we must have applied operation here in forward direction.
                // Reverse: toggle these three positions.
                grid[y][idx] ^= val;
                if (y+1 < height) {
                    grid[y+1][idx] ^= val;
                    grid[y][idx+1] ^= val;
                }
            }
        }
    }

    // After processing, only (X,0) should be on
    int X = -1;
    for (int x = -maxY; x <= maxY; x++) {
        int idx = x + offset;
        if (grid[0][idx]) {
            X = x;
            break;
        }
    }

    printf("%d\n", X);

    for (int i = 0; i < height; i++) free(grid[i]);
    free(grid);
    free(xs);
    free(ys);
    return 0;
}

