int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<pair<int,int>> lamps(N);
    map<pair<int,int>, int> state;

    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        lamps[i] = {x, y};
        state[{x, y}] ^= 1;
    }

    // Compute f(x,y) = state(x,y) ^ state(x+1,y) ^ state(x,y+1)
    map<pair<int,int>, int> f;
    for (auto &[p, v] : state) {
        int x = p.first, y = p.second;
        // f(x,y) and f(x-1,y) and f(x,y-1) might be affected
        for (auto [dx, dy] : vector<pair<int,int>>{{0,0}, {-1,0}, {0,-1}}) {
            int nx = x + dx, ny = y + dy;
            int v1 = state[{nx, ny}];
            int v2 = state[{nx+1, ny}];
            int v3 = state[{nx, ny+1}];
            f[{nx, ny}] = v1 ^ v2 ^ v3;
        }
    }

    // Find all f that are 1
    vector<pair<int,int>> ones;
    for (auto &[p, v] : f) {
        if (v) ones.push_back(p);
    }

    // Initially, f is 1 only at (X-1,0) and (X,0)
    // So we must have exactly two ones in f, with y=0 and consecutive x
    if (ones.size() != 2) {
        // Should not happen for valid input
        cout << -1 << "\n";
        return 0;
    }

    auto [x1, y1] = ones[0];
    auto [x2, y2] = ones[1];

    if (y1 != 0 || y2 != 0 || abs(x1 - x2) != 1) {
        cout << -1 << "\n";
        return 0;
    }

    int X = max(x1, x2);
    cout << X << "\n";

    return 0;
}

