import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] xs = new int[N];
        int[] ys = new int[N];
        for (int i = 0; i < N; i++) {
            xs[i] = sc.nextInt();
            ys[i] = sc.nextInt();
        }

        // The operation toggles (x,y), (x,y+1), (x+1,y).
        // Starting from (X,0) on, final configuration must satisfy:
        // For each diagonal (x+y = constant), parity condition determines X.

        // We can check possible X by looking at constraints:
        // Actually a known approach: the only possible X is determined by
        // looking at the smallest x coordinate among points with y=0, or similar.

        // Key insight: operation adds 1 to sum over all coordinates mod 2 in a certain way.
        // The sum over all target points of (x + y) mod 2 equals (X mod 2).

        int paritySum = 0;
        for (int i = 0; i < N; i++) {
            paritySum ^= ((xs[i] + ys[i]) & 1);
        }

        // paritySum = X & 1

        // Now find min x among points with y=0, call it minX0.
        // The starting X must be ≤ minX0, and parity matches.
        // Actually X is uniquely determined as the minimum possible value.

        int minX0 = Integer.MAX_VALUE;
        for (int i = 0; i < N; i++) {
            if (ys[i] == 0) {
                minX0 = Math.min(minX0, xs[i]);
            }
        }

        // If no point with y=0, then X can be any integer with right parity.
        // But problem guarantees unique solution.

        if (minX0 == Integer.MAX_VALUE) {
            // Pick smallest X matching parity
            int X = (paritySum == 0) ? 0 : 1;
            // Find minimum X >= 0 with correct parity and such that it's reachable:
            // For empty y=0, X can be any number with that parity, pick smallest non-negative.
            System.out.println(X);
        } else {
            // X must be ≤ minX0 and same parity as paritySum
            int X = minX0;
            if ((X & 1) != paritySum) {
                X--;
            }
            System.out.println(X);
        }

        sc.close();
    }
}

