public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        long ans = 0;
        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            if ((y & 1L) == 0) ans ^= x;
            else ans ^= (x + 1);
        }

        System.out.println(ans);
    }
}

import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    N = int(input_data[0])
    points = []
    for i in range(N):
        x = int(input_data[1 + 2*i])
        y = int(input_data[2 + 2*i])
        points.append((x, y))

    # store in a dict for fast access and updates
    on = {}
    for x, y in points:
        on[(x, y)] = True

    # We'll process from max x,y downwards
    max_x = max(x for x, y in points)
    max_y = max(y for x, y in points)

    # To avoid infinite loops, process large to small
    for x in range(max_x, -10, -1):
        for y in range(max_y, -10, -1):
            if on.get((x, y), False):
                # apply operation at (x-1, y-1)
                op_x = x - 1
                op_y = y - 1
                # toggle (op_x, op_y)
                key = (op_x, op_y)
                if on.get(key, False):
                    del on[key]
                else:
                    on[key] = True
                # toggle (op_x, op_y+1)
                key = (op_x, op_y + 1)
                if on.get(key, False):
                    del on[key]
                else:
                    on[key] = True
                # toggle (op_x+1, op_y)
                key = (op_x + 1, op_y)
                if on.get(key, False):
                    del on[key]
                else:
                    on[key] = True

    # After all operations, only (X,0) should remain
    for (x, y) in list(on.keys()):
        if y == 0:
            print(x)
            return

if __name__ == "__main__":
    solve()

